from django.db import migrations, models


def copy_dates_to_event_dates(apps, schema_editor):
    """Every existing event gets one date with its old start and end."""
    db = schema_editor.connection.alias
    Event = apps.get_model("events", "Event")
    EventDate = apps.get_model("events", "EventDate")
    EventDate.objects.using(db).bulk_create(
        EventDate(
            event=event,
            start=event.start_date,
            end=event.end_date,
            show_end=event.show_end_date,
        )
        for event in Event.objects.using(db).all()
    )


def copy_event_dates_back(apps, schema_editor):
    """Reverse: use the first start, the last end of the dates."""
    db = schema_editor.connection.alias
    Event = apps.get_model("events", "Event")
    for event in Event.objects.using(db).all():
        dates = list(event.dates.order_by("start"))
        if dates:
            event.start_date = dates[0].start
            event.end_date = max(date.end for date in dates)
            event.show_end_date = dates[0].show_end
            event.save()


